UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 40, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 41, 7, NULL::text),(3, 169, 30, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 203, 474, NULL::text),(6,0,0,E'c) Todos los elementos o componentes que conforman el Sistema de Escape deben quedar distanciados como mínimo 50 mm (2") con respecto del cableado del sistema de combustible, del sistema de frenos y de cualquier material inflamable, aun cuando éstos estén protegidos por una cubierta.'),(7, 966, 228, NULL::text),(8,0,0,E'e) Los componentes del sistema de escape deben distanciarse como mínimo 50 mm (2"), respecto de cualquier elemento del sistema de combustible, de frenos o de cualquier material combustible, y en las protecciones se acepta una distancia de 25 mm (1"), como el caso del tanque de combustible.'),(9, 1494, 290, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='98c6deea-bf21-597b-a48f-0e103ba04ddb' AND md5(a.contenido)='32d8ea2a237870d151b04ad0dcb18878' RETURNING a.id,md5(a.contenido) hash;